    /// <summary>
    /// Represents the SignalR hub specific for GPS functionalities.
    /// </summary>
    public class SignalRInternalCanbus : BaseHub, ISignalRCanBusHub
    {
        private readonly IGenericRepository<MessageModel> _repository;
        private readonly ILogger<SignalRInternalCanbus> _logger;

        // Constructor with DI for repository and logger
        public SignalRInternalCanbus(
            ISignalRConnectionHandler signalRConnectionHandler,
            IGenericRepository<MessageModel> repository,
            ILogger<SignalRInternalCanbus> logger)
            : base(signalRConnectionHandler)
        {
            _repository = repository ?? throw new ArgumentNullException(nameof(repository));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        }

        public async Task AcknowledgeMessage(string messageId)
        {
            if (string.IsNullOrWhiteSpace(messageId))
            {
                _logger.LogWarning("AcknowledgeMessage called with null or empty messageId from client {ConnectionId}", Context.ConnectionId);
                return;
            }

            try
            {
                // Convert string to Guid
                if (!Guid.TryParse(messageId, out Guid messageGuid))
                {
                    _logger.LogWarning("Invalid GUID format received in AcknowledgeMessage from client {ConnectionId}: {MessageId}", Context.ConnectionId, messageId);
                    return;
                }

                // Delete or mark message as acknowledged in repository
                await _repository.DeleteAsync(messageGuid);

                _logger.LogInformation("Message {MessageId} acknowledged and deleted by client {ConnectionId}", messageGuid, Context.ConnectionId);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing AcknowledgeMessage for message {MessageId} from client {ConnectionId}", messageId, Context.ConnectionId);
                // Optionally rethrow or handle the error depending on your architecture
            }
        }
    }
}
